/* The signature view shares the atlas's existing motion preference. */
(()=>{'use strict';const button=document.querySelector('#signature-motion');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let mode;try{mode=localStorage.getItem('atlas-motion');}catch{}if(mode!=='on'&&mode!=='off')mode=reduced.matches?'off':'on';const apply=()=>{document.documentElement.dataset.motion=mode;if(button){button.textContent=mode==='off'?'RESUME MOTION':'PAUSE MOTION';button.setAttribute('aria-pressed',String(mode==='off'));}};apply();button?.addEventListener('click',()=>{mode=mode==='off'?'on':'off';try{localStorage.setItem('atlas-motion',mode);}catch{}apply();});})();
